def transfer_reference() -> str:
    """New bank-transfer payment reference, e.g. "K7QM-X2PA-9BRC".

    12 characters in three dash-separated groups of four, drawn from the same
    unambiguous alphabet as the shop's other customer-facing codes (no 0/O,
    1/I/L), since it gets typed from printed invoices and read over the phone.
    """
    return short_code(12, groups=4)


